    size_t n,
    size_t k
) {
    __shared__ uint64_t tile_a[MATMUL_TILE_DIM][MATMUL_TILE_DIM];
    __shared__ uint64_t tile_b[MATMUL_TILE_DIM][MATMUL_TILE_DIM];

    size_t row = (size_t)blockIdx.y * MATMUL_TILE_DIM + (size_t)threadIdx.y;
    size_t col = (size_t)blockIdx.x * MATMUL_TILE_DIM + (size_t)threadIdx.x;

    uint64_t acc = 0;
    size_t num_tiles = (k + MATMUL_TILE_DIM - 1) / MATMUL_TILE_DIM;

    for (size_t t = 0; t < num_tiles; ++t) {
        size_t a_col = t * MATMUL_TILE_DIM + (size_t)threadIdx.x;
        size_t b_row = t * MATMUL_TILE_DIM + (size_t)threadIdx.y;

        tile_a[threadIdx.y][threadIdx.x] = (row < m && a_col < k) ? a[row * k + a_col] : 0ULL;
        tile_b[threadIdx.y][threadIdx.x] = (b_row < k && col < n) ? b[b_row * n + col] : 0ULL;
        __syncthreads();

        #pragma unroll
        for (int p = 0; p < MATMUL_TILE_DIM; ++p) {
            acc += tile_a[threadIdx.y][p] * tile_b[p][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < m && col < n) {
        c[row * n + col] = acc;
    }
